export {
  defineActions,
  type ActionDefinitionBase,
  type DefinedActions,
  type DefineActionsOptions,
} from "./define-actions";
export {
  ROW_ACTIONS_KEY,
  type ActionDescriptor,
  type ActionError,
  type ActionErrorCode,
  type ActionRequest,
  type ActionResponse,
  type ActionScope,
  type ActionVariant,
  type WithRowActions,
} from "./types";

import type { Filters } from "@/lib/filters";
import {
  ROW_ACTIONS_KEY,
  type ActionDescriptor,
  type ActionScope,
  type ActionVariant,
  type WithRowActions,
} from "./types";

/**
 * The declarative half of an action — everything except how it executes.
 *
 * `createActionHandler` (Drizzle) adds the `handler`; this module never looks
 * at it, which is what keeps `annotate` and `descriptors` importable anywhere.
 */
export type ActionDefinitionBase<TRow = Record<string, unknown>> = {
  label: string;
  /** Defaults to `["row", "bulk"]`. */
  scope?: ActionScope[];
  variant?: ActionVariant;
  /** Confirmation copy. `{count}` is replaced with the affected row count. */
  confirm?: string;
  /**
   * Availability, as filter values — `{ status: ["dead"] }` — in exactly the
   * shape the list endpoint reads from its search params.
   *
   * One declaration, two engines: `filters.matches` evaluates it per row to
   * compute `_actions`, and the SQL engine compiles it into the handler's WHERE
   * guard. Keys must be filterable columns; anything else throws at
   * construction rather than silently matching every row.
   */
  when?: Record<string, unknown>;
  /**
   * JS-only escape hatch for availability the filter semantics cannot express
   * (a computed field, a non-filterable column). It only shapes `_actions`;
   * there is no SQL counterpart, so the handler must guard itself.
   */
  available?: (row: TRow) => boolean;
};

export type DefineActionsOptions = {
  /** `href` is `${basePath}/${id}`. */
  basePath: string;
};

export type DefinedActions<TDef extends ActionDefinitionBase<never>> = {
  /** The declarations, with defaults applied. Keyed by id. */
  definitions: ReadonlyMap<string, TDef & { scope: ActionScope[] }>;
  /** Public metadata for the wire. Same order as declared. */
  descriptors: ActionDescriptor[];
  /** Stamp every row with the ids it currently qualifies for. */
  annotate<TRow>(rows: readonly TRow[]): WithRowActions<TRow>[];
  /** The ids one row qualifies for. */
  actionsFor(row: unknown): string[];
};

const DEFAULT_SCOPE: ActionScope[] = ["row", "bulk"];

/** An id is a URL segment and an audit-log key. Keep it boring. */
const ID_PATTERN = /^[a-z0-9][a-z0-9_-]*$/;

/**
 * The pick-list. Adding a field to `ActionDescriptor` fails to compile here
 * until it is either projected or deliberately excluded — the failure mode
 * this guards against is `{ ...definition }` leaking a handler, a secret, or a
 * `when` clause the server never meant to publish.
 */
const PUBLIC_KEYS = {
  id: true,
  label: true,
  scope: true,
  variant: true,
  confirm: true,
  href: true,
} as const satisfies Record<keyof ActionDescriptor, true>;

type _PublicKeysExhaustive = [
  Exclude<keyof ActionDescriptor, keyof typeof PUBLIC_KEYS>,
] extends [never]
  ? true
  : never;
const _publicKeysExhaustive: _PublicKeysExhaustive = true;
void _publicKeysExhaustive;

function toDescriptor(
  id: string,
  definition: ActionDefinitionBase<never> & { scope: ActionScope[] },
  basePath: string,
): ActionDescriptor {
  const descriptor: ActionDescriptor = {
    id,
    label: definition.label,
    scope: [...definition.scope],
    href: `${basePath}/${id}`,
  };
  // Optional keys are only present when set, so the JSON stays canonical.
  if (definition.variant !== undefined) descriptor.variant = definition.variant;
  if (definition.confirm !== undefined) descriptor.confirm = definition.confirm;
  return descriptor;
}

/**
 * Validate a `when` clause against the declared filter semantics.
 *
 * `filters.plan` silently drops unknown keys and inactive values, which is
 * right for search params and wrong for an availability guard: a typo would
 * turn "only dead rows" into "every row". So every key must be a spec, and
 * every value must plan to an op.
 */
function assertWhen(
  id: string,
  when: Record<string, unknown>,
  filters: Filters,
): void {
  for (const key of Object.keys(when)) {
    if (!filters.spec(key)) {
      throw new Error(
        `[defineActions] Action "${id}": when.${JSON.stringify(key)} is not a filterable column. ` +
          `Filterable: ${filters.specs.map((spec) => spec.key).join(", ") || "(none)"}`,
      );
    }
    const ops = filters.plan({ [key]: when[key] });
    if (ops.length === 0) {
      throw new Error(
        `[defineActions] Action "${id}": when.${JSON.stringify(key)} is not an active filter value ` +
          `(got ${JSON.stringify(when[key])}). An empty guard would match every row.`,
      );
    }
  }
}

/**
 * Turn action declarations into the two things the rest of the system needs:
 * public descriptors for the wire, and a per-row availability stamp.
 *
 * Generic over the definition type so the Drizzle handler can carry its
 * `handler` through without this module depending on Drizzle.
 */
export function defineActions<TDef extends ActionDefinitionBase<never>>(
  filters: Filters,
  actions: Record<string, TDef>,
  options: DefineActionsOptions,
): DefinedActions<TDef> {
  const basePath = options.basePath.replace(/\/+$/, "");
  if (basePath.length === 0) {
    throw new Error(`[defineActions] basePath must be a non-empty path`);
  }

  const definitions = new Map<string, TDef & { scope: ActionScope[] }>();
  const descriptors: ActionDescriptor[] = [];

  for (const [id, definition] of Object.entries(actions)) {
    if (!ID_PATTERN.test(id)) {
      throw new Error(
        `[defineActions] Action id ${JSON.stringify(id)} must match ${ID_PATTERN} — it becomes a URL segment.`,
      );
    }
    if (!definition.label) {
      throw new Error(`[defineActions] Action "${id}" needs a label`);
    }

    const scope = Array.from(new Set(definition.scope ?? DEFAULT_SCOPE));
    if (scope.length === 0) {
      throw new Error(`[defineActions] Action "${id}" declares an empty scope`);
    }

    if (definition.when) assertWhen(id, definition.when, filters);

    const withDefaults = { ...definition, scope };
    definitions.set(id, withDefaults);
    descriptors.push(toDescriptor(id, withDefaults, basePath));
  }

  const actionsFor = (row: unknown): string[] => {
    const ids: string[] = [];
    for (const [id, definition] of definitions) {
      if (definition.when && !filters.matches(definition.when, row)) continue;
      if (definition.available && !definition.available(row as never)) continue;
      ids.push(id);
    }
    return ids;
  };

  return {
    definitions,
    descriptors,
    actionsFor,
    annotate: (rows) =>
      rows.map((row) => ({ ...row, [ROW_ACTIONS_KEY]: actionsFor(row) })),
  };
}

import {
  defineActions,
  type ActionDefinitionBase,
  type ActionDescriptor,
  type ActionErrorCode,
  type ActionRequest,
  type ActionResponse,
  type WithRowActions,
} from "@/lib/actions";
import type { Filters } from "@/lib/filters";
import { and, count, inArray, sql, type SQL } from "drizzle-orm";
import type { PgTable } from "drizzle-orm/pg-core";
import { z } from "zod";
import { buildWhereConditions } from "./filters";
import type { ColumnMapping, DrizzleDB } from "./types";

/**
 * What a handler receives.
 *
 * `where` is the authority: the requested set (ids, or a filter) intersected
 * with the action's `when` guard. A handler that uses it cannot touch a row
 * the action does not apply to, no matter what the client sent.
 */
export type ActionContext = {
  where: SQL;
  /** Present for `scope: "ids"`. */
  ids?: string[];
  /** Present for `scope: "filter"` — already passed through `filters.coerce`. */
  filter?: Record<string, unknown>;
  /** Whoever the route authenticated. Never read from the request body. */
  actor?: string;
  /** Client-generated; at-least-once, see `ActionRequest`. */
  cmdId: string;
};

export type DrizzleActionDefinition<TRow = Record<string, unknown>> =
  ActionDefinitionBase<TRow> & {
    /**
     * Runs inside one transaction and returns how many rows it applied to.
     *
     * Actions enqueue; they don't execute. A replay flips `status` to
     * `pending` and lets the worker do the work — that is why one short
     * transaction is enough and why nothing here does I/O.
     *
     * ```ts
     * handler: async (ctx, tx) => {
     *   const rows = await tx
     *     .update(outbox)
     *     .set({ status: "pending", attempt: 0 })
     *     .where(ctx.where)
     *     .returning({ id: outbox.id });
     *   return rows.length;
     * }
     * ```
     */
    handler: (ctx: ActionContext, tx: DrizzleDB) => Promise<number>;
  };

export type ActionAuditEvent = {
  action: string;
  actor?: string;
  cmdId: string;
  scope: ActionRequest["scope"];
  ids?: string[];
  filter?: Record<string, unknown>;
  applied: number;
  at: Date;
};

export type ActionHandlerConfig<TRow = Record<string, unknown>> = {
  db: DrizzleDB;
  table: PgTable;
  /** The same `defineFilters(...)` the list handler uses. */
  filters: Filters;
  columnMapping: ColumnMapping;
  /** The schema key that identifies a row. Must be in `columnMapping`. */
  idColumn: string;
  actions: Record<string, DrizzleActionDefinition<TRow>>;
  /** `href` is `${basePath}/${id}` — the route that calls `execute`. */
  basePath: string;
  /** Upper bound on `ids.length`; larger requests are `invalid_request`. */
  maxIds?: number;
  /**
   * Called once per applied command, after the transaction committed. If it
   * throws, the mutation has already happened — the error propagates so the
   * route can decide, but nothing is rolled back.
   */
  audit?: (event: ActionAuditEvent) => void | Promise<void>;
};

const STATUS_BY_CODE: Record<ActionErrorCode, number> = {
  unknown_action: 404,
  scope_not_allowed: 400,
  invalid_request: 400,
  count_mismatch: 409,
  forbidden: 403,
  failed: 500,
};

/** A typed failure the route maps to an HTTP response. */
export class ActionHandlerError extends Error {
  readonly code: ActionErrorCode;
  readonly status: number;
  /** Present on `count_mismatch`. */
  readonly actual?: number;

  constructor(code: ActionErrorCode, message: string, actual?: number) {
    super(message);
    this.name = "ActionHandlerError";
    this.code = code;
    this.status = STATUS_BY_CODE[code];
    if (actual !== undefined) this.actual = actual;
  }

  /** The JSON body for the wire. */
  toJSON(): { error: ActionErrorCode; actual?: number } {
    return this.actual === undefined
      ? { error: this.code }
      : { error: this.code, actual: this.actual };
  }
}

const requestSchema = z.discriminatedUnion("scope", [
  z.object({
    scope: z.literal("ids"),
    ids: z.array(z.string().min(1)).min(1),
    cmd_id: z.string().min(1),
  }),
  z.object({
    scope: z.literal("filter"),
    filter: z.record(z.string(), z.unknown()),
    expected_count: z.number().int().nonnegative().optional(),
    cmd_id: z.string().min(1),
  }),
]);

export type ActionHandler<TRow = Record<string, unknown>> = {
  /** Public metadata for `meta.actions`. */
  descriptors: ActionDescriptor[];
  /** Stamp fetched rows with `_actions`. */
  annotate<T extends TRow>(rows: readonly T[]): WithRowActions<T>[];
  /**
   * Run one action. Throws `ActionHandlerError` for every contract violation;
   * anything else that escapes is the handler's own failure, already rolled
   * back.
   */
  execute(
    actionId: string,
    body: unknown,
    options?: { actor?: string },
  ): Promise<ActionResponse>;
};

/**
 * The write-side sibling of `createDrizzleHandler`.
 *
 * Shares its `filters` and `columnMapping`, so an action's `when` guard and a
 * filter-scoped request compile through the very same `buildWhereConditions`
 * the list endpoint uses — the set the user saw is the set the action hits.
 */
export function createActionHandler<TRow = Record<string, unknown>>(
  config: ActionHandlerConfig<TRow>,
): ActionHandler<TRow> {
  const {
    db,
    table,
    filters,
    columnMapping,
    idColumn,
    basePath,
    maxIds = 1000,
    audit,
  } = config;

  const idCol = columnMapping[idColumn];
  if (!idCol) {
    throw new Error(
      `[createActionHandler] idColumn "${idColumn}" not found in columnMapping`,
    );
  }

  // Mirror `createDrizzleHandler`: `buildWhereConditions` skips a key that is
  // missing from the mapping. For a `when` guard that would mean "every row";
  // for a filter-scoped request, "more rows than the user saw". Fail here.
  const unmapped = filters.specs
    .map((spec) => spec.key)
    .filter((key) => !columnMapping[key]);
  if (unmapped.length > 0) {
    throw new Error(
      `[createActionHandler] These filterable columns are missing from columnMapping:\n` +
        unmapped.map((key) => `  - ${key}`).join("\n"),
    );
  }

  const defined = defineActions<DrizzleActionDefinition<TRow>>(
    filters,
    config.actions,
    { basePath },
  );

  // `when` guards never change after construction, so compile them once.
  const guards = new Map<string, SQL[]>();
  for (const [id, definition] of defined.definitions) {
    guards.set(
      id,
      definition.when
        ? buildWhereConditions(filters, definition.when, columnMapping)
        : [],
    );
  }

  async function execute(
    actionId: string,
    body: unknown,
    options: { actor?: string } = {},
  ): Promise<ActionResponse> {
    const definition = defined.definitions.get(actionId);
    if (!definition) {
      throw new ActionHandlerError("unknown_action", `No action "${actionId}"`);
    }

    const parsed = requestSchema.safeParse(body);
    if (!parsed.success) {
      throw new ActionHandlerError(
        "invalid_request",
        `Invalid request body: ${parsed.error.issues.map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`).join("; ")}`,
      );
    }
    const request = parsed.data;

    const guard = guards.get(actionId) ?? [];
    let where: SQL;
    /** The set the client counted — the filter alone, before the guard. */
    let shown: SQL | undefined;
    let ids: string[] | undefined;
    let filter: Record<string, unknown> | undefined;

    if (request.scope === "ids") {
      const allowed =
        definition.scope.includes("row") || definition.scope.includes("bulk");
      if (!allowed) {
        throw new ActionHandlerError(
          "scope_not_allowed",
          `Action "${actionId}" does not accept ids (scope: ${definition.scope.join(", ")})`,
        );
      }
      if (!definition.scope.includes("bulk") && request.ids.length > 1) {
        throw new ActionHandlerError(
          "scope_not_allowed",
          `Action "${actionId}" accepts one id at a time (scope: ${definition.scope.join(", ")})`,
        );
      }
      if (request.ids.length > maxIds) {
        throw new ActionHandlerError(
          "invalid_request",
          `Too many ids (${request.ids.length} > ${maxIds}); use scope "filter"`,
        );
      }
      ids = Array.from(new Set(request.ids));
      where = and(inArray(idCol, ids), ...guard)!;
    } else {
      if (!definition.scope.includes("filter")) {
        throw new ActionHandlerError(
          "scope_not_allowed",
          `Action "${actionId}" does not accept a filter (scope: ${definition.scope.join(", ")})`,
        );
      }
      // The same interpretation as the list endpoint: `filters.plan` (inside
      // `buildWhereConditions`) drops unknown keys and inactive values and
      // never clamps. `filters.coerce` would clamp a slider to its declared
      // bounds — and a range the user dragged past those bounds must hit the
      // rows they saw, not a narrower set. Unknown keys are dropped from the
      // recorded filter as well.
      filter = Object.fromEntries(
        Object.entries(request.filter).filter(
          ([key]) => filters.spec(key) !== undefined,
        ),
      );
      const visible = buildWhereConditions(filters, filter, columnMapping);
      // An empty filter is "every row". Legal — `expected_count` is the
      // client's safety net — but the handler still gets a real SQL.
      shown = and(...visible) ?? sql`true`;
      where = and(...visible, ...guard) ?? sql`true`;
    }

    const ctx: ActionContext = {
      where,
      cmdId: request.cmd_id,
      ...(ids ? { ids } : {}),
      ...(filter ? { filter } : {}),
      ...(options.actor !== undefined ? { actor: options.actor } : {}),
    };
    const expectedCount =
      request.scope === "filter" ? request.expected_count : undefined;

    const applied = await db.transaction(async (tx) => {
      if (expectedCount !== undefined && shown !== undefined) {
        // Drift is measured on the set the client was shown, not on the
        // guarded set: a guard makes `applied` smaller by design, and that is
        // not "the set changed".
        const [row] = await tx.select({ n: count() }).from(table).where(shown);
        const actual = Number(row?.n ?? 0);
        if (actual !== expectedCount) {
          throw new ActionHandlerError(
            "count_mismatch",
            `Expected ${expectedCount} rows, found ${actual}`,
            actual,
          );
        }
      }
      const result = await definition.handler(ctx, tx);
      if (typeof result !== "number" || !Number.isFinite(result)) {
        throw new Error(
          `[createActionHandler] Action "${actionId}" handler must return the applied row count, got ${String(result)}`,
        );
      }
      return result;
    });

    if (audit) {
      await audit({
        action: actionId,
        cmdId: request.cmd_id,
        scope: request.scope,
        applied,
        at: new Date(),
        ...(ids ? { ids } : {}),
        ...(filter ? { filter } : {}),
        ...(options.actor !== undefined ? { actor: options.actor } : {}),
      });
    }

    return { applied };
  }

  return {
    descriptors: defined.descriptors,
    annotate: (rows) => defined.annotate(rows),
    execute,
  };
}

export { DataTableActionsBar } from "./bar";
export { createActionsColumn, DataTableActionsCell } from "./column";
export {
  DataTableActionsConfirmDialog,
  describePending,
  type PendingCommandView,
} from "./confirm-dialog";
export { DataTableActionsFilterMenu, pickFilterValues } from "./filter-menu";
export {
  DataTableActionsProvider,
  useDataTableActions,
  type ActionRequestInput,
  type AppliedEvent,
  type DataTableActionsContextValue,
  type DataTableActionsProviderProps,
  type TriggerMeta,
} from "./provider";
export {
  ActionRequestError,
  actionsForScope,
  interpolate,
  newCommandId,
  partitionRows,
  postAction,
  rowActionsOf,
  rowScopedActions,
} from "./utils";

"use client";

import type {
  ActionDescriptor,
  ActionRequest,
  ActionResponse,
} from "@/lib/actions/types";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import * as React from "react";
import { toast } from "sonner";
import {
  DataTableActionsConfirmDialog,
  type PendingCommandView,
} from "./confirm-dialog";
import {
  ActionRequestError,
  newCommandId,
  postAction,
  rowActionsOf,
} from "./utils";

type DistributiveOmit<T, K extends keyof T> = T extends unknown
  ? Omit<T, K>
  : never;

/** A request minus the `cmd_id` the provider stamps on at send time. */
export type ActionRequestInput = DistributiveOmit<ActionRequest, "cmd_id">;

export type TriggerMeta = {
  /** How many rows the user was shown. */
  count: number;
  /** Selected rows the action does not apply to. */
  skipped?: number;
  /** Runs after a 2xx — e.g. clear the selection the action consumed. */
  onApplied?: () => void;
};

export type AppliedEvent = {
  action: ActionDescriptor;
  request: ActionRequest;
  response: ActionResponse;
};

export type DataTableActionsContextValue<TData = unknown> = {
  actions: ActionDescriptor[];
  getRowId: (row: TData) => string;
  getRowActions: (row: TData) => string[];
  /**
   * Start an action. Opens the confirmation if the descriptor asks for one,
   * otherwise sends immediately. A `count_mismatch` reopens the dialog with
   * the server's number and offers to apply anyway.
   */
  trigger: (
    action: ActionDescriptor,
    request: ActionRequestInput,
    meta: TriggerMeta,
  ) => void;
  isPending: boolean;
};

const DataTableActionsContext =
  React.createContext<DataTableActionsContextValue<never> | null>(null);

export function useDataTableActions<TData = unknown>() {
  const context = React.useContext(DataTableActionsContext);
  if (!context) {
    throw new Error(
      "useDataTableActions must be used within a DataTableActionsProvider",
    );
  }
  return context as unknown as DataTableActionsContextValue<TData>;
}

type PendingCommand = PendingCommandView & {
  request: ActionRequestInput;
  onApplied?: () => void;
};

export type DataTableActionsProviderProps<TData> = {
  /** From `meta.actions`. `undefined` while loading renders no buttons. */
  actions?: ActionDescriptor[];
  getRowId: (row: TData) => string;
  /** Defaults to the server's `_actions` stamp. */
  getRowActions?: (row: TData) => string[];
  /**
   * The first element of the table's query key. Every page under it is
   * invalidated after a successful action, so rows that no longer match
   * leave the view.
   */
  queryKeyPrefix?: string;
  onApplied?: (event: AppliedEvent) => void;
  /** Injected in tests. */
  fetcher?: typeof fetch;
  children: React.ReactNode;
};

export function DataTableActionsProvider<TData>({
  actions,
  getRowId,
  getRowActions,
  queryKeyPrefix,
  onApplied,
  fetcher,
  children,
}: DataTableActionsProviderProps<TData>) {
  const queryClient = useQueryClient();
  const [pending, setPending] = React.useState<PendingCommand | null>(null);

  const mutation = useMutation({
    mutationFn: (variables: {
      action: ActionDescriptor;
      request: ActionRequest;
      meta: TriggerMeta;
    }) => postAction(variables.action.href, variables.request, fetcher),
    onSuccess: (response, { action, request, meta }) => {
      if (request.scope === "filter") {
        // The client counted the filter-only set; the server applied within
        // the action's guard. A smaller number is the guard at work, not a
        // partial failure.
        toast.success(
          `${action.label}: applied to ${response.applied} of ${meta.count} matching`,
        );
      } else if (response.applied < request.ids.length) {
        // Only eligible ids were sent, so a shortfall means rows changed
        // between fetch and click.
        toast.warning(
          `${action.label}: applied to ${response.applied} of ${request.ids.length}`,
        );
      } else {
        toast.success(`${action.label}: applied to ${response.applied}`);
      }
      if (queryKeyPrefix) {
        void queryClient.invalidateQueries({ queryKey: [queryKeyPrefix] });
      }
      meta.onApplied?.();
      onApplied?.({ action, request, response });
    },
    onError: (error, { action, request, meta }) => {
      if (
        error instanceof ActionRequestError &&
        error.code === "count_mismatch" &&
        request.scope === "filter"
      ) {
        const { cmd_id: _cmdId, ...input } = request;
        setPending({
          action,
          request: input,
          count: meta.count,
          skipped: meta.skipped ?? 0,
          scope: "filter",
          actual: error.actual ?? 0,
          onApplied: meta.onApplied,
        });
        return;
      }
      toast.error(`${action.label} failed: ${error.message}`);
    },
  });

  // `mutate` is referentially stable; the result object is not, and depending
  // on it would rebuild `trigger` — and the context value — on every render.
  const { mutate, isPending } = mutation;

  const send = React.useCallback(
    (
      action: ActionDescriptor,
      request: ActionRequestInput,
      meta: TriggerMeta,
    ) => {
      mutate({
        action,
        request: { ...request, cmd_id: newCommandId() } as ActionRequest,
        meta,
      });
    },
    [mutate],
  );

  const trigger = React.useCallback<
    DataTableActionsContextValue<TData>["trigger"]
  >(
    (action, request, meta) => {
      if (action.confirm) {
        setPending({
          action,
          request,
          count: meta.count,
          skipped: meta.skipped ?? 0,
          scope: request.scope,
          onApplied: meta.onApplied,
        });
        return;
      }
      send(action, request, meta);
    },
    [send],
  );

  const confirm = React.useCallback(() => {
    if (!pending) return;
    const { action, request, count, skipped, actual, onApplied } = pending;
    setPending(null);
    if (actual !== undefined && request.scope === "filter") {
      // The user accepted the server's number: drop the optimistic check.
      const { expected_count: _expected, ...rest } = request;
      send(action, rest, { count: actual, skipped, onApplied });
      return;
    }
    send(action, request, { count, skipped, onApplied });
  }, [pending, send]);

  const cancel = React.useCallback(() => setPending(null), []);

  const value = React.useMemo<DataTableActionsContextValue<TData>>(
    () => ({
      actions: actions ?? [],
      getRowId,
      getRowActions: getRowActions ?? rowActionsOf,
      trigger,
      isPending,
    }),
    [actions, getRowId, getRowActions, trigger, isPending],
  );

  return (
    <DataTableActionsContext.Provider
      value={value as unknown as DataTableActionsContextValue<never>}
    >
      {children}
      <DataTableActionsConfirmDialog
        pending={pending}
        onConfirm={confirm}
        onCancel={cancel}
      />
    </DataTableActionsContext.Provider>
  );
}

"use client";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import type { ActionDescriptor } from "@/lib/actions/types";
import { interpolate } from "./utils";

export type PendingCommandView = {
  action: ActionDescriptor;
  /** How many rows the user was shown. */
  count: number;
  /** Selected rows the action does not apply to. */
  skipped: number;
  /** `filter` scope applies to every matching row, not a selection. */
  scope: "ids" | "filter";
  /** Set when the server answered `count_mismatch`. */
  actual?: number;
};

export function describePending(pending: PendingCommandView): {
  title: string;
  description: string | null;
} {
  const { action, count, skipped, scope, actual } = pending;

  if (actual !== undefined) {
    return {
      title: `${action.label}: the matching set changed`,
      description: `You were shown ${count} ${plural(count, "row")}; the server now counts ${actual}. Apply to ${actual} ${plural(actual, "row")} anyway?`,
    };
  }

  const title = interpolate(
    action.confirm ?? `${action.label} {count} ${plural(count, "row")}?`,
    { count },
  );
  const parts: string[] = [];
  if (scope === "filter") {
    parts.push("Applies to every row matching the current filters.");
  }
  if (skipped > 0) {
    parts.push(
      `${skipped} selected ${plural(skipped, "row")} ${skipped === 1 ? "does" : "do"} not qualify and will be skipped.`,
    );
  }
  return { title, description: parts.length > 0 ? parts.join(" ") : null };
}

function plural(n: number, noun: string): string {
  return n === 1 ? noun : `${noun}s`;
}

export function DataTableActionsConfirmDialog({
  pending,
  onConfirm,
  onCancel,
}: {
  pending: PendingCommandView | null;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const copy = pending ? describePending(pending) : null;
  const destructive = pending?.action.variant === "destructive";

  return (
    <AlertDialog
      open={pending !== null}
      onOpenChange={(open) => {
        if (!open) onCancel();
      }}
    >
      <AlertDialogContent size="sm">
        <AlertDialogHeader>
          <AlertDialogTitle>{copy?.title}</AlertDialogTitle>
          {copy?.description ? (
            <AlertDialogDescription>{copy.description}</AlertDialogDescription>
          ) : null}
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            variant={destructive ? "destructive" : "default"}
            onClick={onConfirm}
          >
            {pending?.actual !== undefined
              ? "Apply anyway"
              : (pending?.action.label ?? "Confirm")}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

